// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb;

/**
 * Thrown by a build worker that met an overflowed record while replaying the commit log above its pinned snapshot: the
 * candidate cannot be brought past that revision, and the applier retries with a pin at or beyond it.
 */
final class AdjacencyGapException extends Exception {

	private static final long serialVersionUID = 1L;

	private final long revision;

	AdjacencyGapException(long revision) {
		super("commit log revision " + revision + " is a gap");
		this.revision = revision;
	}

	long revision() {
		return revision;
	}
}
